package com.andye.warmod.icbm.guidance;import com.andye.warmod.block.MissileSiloGuidanceFrameStructure;import java.util.SplittableRandom;import java.util.UUID;import java.util.function.Predicate;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;public final class IcbmGuidanceResolver {private static final long SALT=0x47554944414E4345L;private IcbmGuidanceResolver(){}public static IcbmGuidanceResolution resolve(IcbmGuidanceProfile p,UUID missileId,Predicate<Vec3> valid){double max=MissileSiloGuidanceFrameStructure.maximumGuidanceError(p.guidanceTier());if(max<=0)return new IcbmGuidanceResolution(p.guidanceTier(),p.requestedTarget(),p.requestedTarget(),0,0,0);for(int attempt=0;attempt<8;attempt++){long seed=mix(p.guidanceSeed()^missileId.getMostSignificantBits()^Long.rotateLeft(missileId.getLeastSignificantBits(),23)^SALT^(attempt*0x9E3779B97F4A7C15L));SplittableRandom r=new SplittableRandom(seed);double u1=Math.max(1.0E-12,r.nextDouble()),u2=r.nextDouble();double mag=Math.sqrt(-2.0*Math.log(u1)),angle=Math.PI*2.0*u2,sigma=max/2.5;double dx=Math.rint(Mth.clamp(Math.cos(angle)*mag*sigma,-max,max)),dz=Math.rint(Mth.clamp(Math.sin(angle)*mag*sigma,-max,max));Vec3 candidate=p.requestedTarget().add(dx,0,dz);if(valid.test(candidate))return new IcbmGuidanceResolution(p.guidanceTier(),p.requestedTarget(),candidate,dx,dz,attempt);}return new IcbmGuidanceResolution(p.guidanceTier(),p.requestedTarget(),p.requestedTarget(),0,0,8);}private static long mix(long z){z=(z^(z>>>30))*0xbf58476d1ce4e5b9L;z=(z^(z>>>27))*0x94d049bb133111ebL;return z^(z>>>31);}}